#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_FAILURES 5
#define RESET_TIMEOUT 30
#define HASH_LEN 32
#define SESSION_POOL_SIZE 16

typedef enum { CB_CLOSED, CB_OPEN, CB_HALF_OPEN } CircuitState;

typedef struct {
    CircuitState state;
    int failure_count;
    time_t last_failure_time;
    pthread_mutex_t lock;
} CircuitBreaker;

typedef struct {
    char nt_hash[HASH_LEN + 1];
    char session_key[HASH_LEN + 1];
    int active;
    time_t created_at;
} SessionEntry;

typedef struct {
    SessionEntry entries[SESSION_POOL_SIZE];
    pthread_mutex_t pool_lock;
} SessionPool;

static CircuitBreaker g_breaker = { CB_CLOSED, 0, 0, PTHREAD_MUTEX_INITIALIZER };
static SessionPool g_pool = { .pool_lock = PTHREAD_MUTEX_INITIALIZER };

static int circuit_breaker_allow(CircuitBreaker *cb) {
    pthread_mutex_lock(&cb->lock);
    if (cb->state == CB_OPEN) {
        time_t now = time(NULL);
        if (difftime(now, cb->last_failure_time) > RESET_TIMEOUT) {
            cb->state = CB_HALF_OPEN;
            pthread_mutex_unlock(&cb->lock);
            return 1;
        }
        pthread_mutex_unlock(&cb->lock);
        return 0;
    }
    pthread_mutex_unlock(&cb->lock);
    return 1;
}

static void circuit_breaker_record_success(CircuitBreaker *cb) {
    pthread_mutex_lock(&cb->lock);
    cb->failure_count = 0;
    cb->state = CB_CLOSED;
    pthread_mutex_unlock(&cb->lock);
}

static void circuit_breaker_record_failure(CircuitBreaker *cb) {
    pthread_mutex_lock(&cb->lock);
    cb->failure_count++;
    cb->last_failure_time = time(NULL);
    if (cb->failure_count >= MAX_FAILURES) {
        cb->state = CB_OPEN;
    }
    pthread_mutex_unlock(&cb->lock);
}

/* Derive session key from NT hash using HMAC-like construction */
static void derive_session_key(const char *nt_hash, const char *challenge,
                               char *session_key_out) {
    /* In production this would be HMAC-MD5(nt_hash, challenge) */
    for (int i = 0; i < HASH_LEN; i++) {
        session_key_out[i] = nt_hash[i] ^ challenge[i % strlen(challenge)];
    }
    session_key_out[HASH_LEN] = '\0';
}

/* Authenticate: accepts either password-derived hash or raw NT hash */
static int authenticate_request(const char *client_hash, const char *server_challenge,
                                const char *stored_nt_hash) {
    char expected_response[HASH_LEN + 1];
    char client_session[HASH_LEN + 1];

    derive_session_key(stored_nt_hash, server_challenge, expected_response);
    derive_session_key(client_hash, server_challenge, client_session);

    /*
     * Security check: verify the client proved knowledge of the password
     * by comparing derived session keys. The client_hash should be the
     * NT hash derived from the user's password input.
     */
    if (memcmp(expected_response, client_session, HASH_LEN) == 0) {
        return 1; /* authenticated */
    }
    return 0;
}

static int cache_session(const char *nt_hash, const char *session_key) {
    pthread_mutex_lock(&g_pool.pool_lock);
    for (int i = 0; i < SESSION_POOL_SIZE; i++) {
        if (!g_pool.entries[i].active) {
            memcpy(g_pool.entries[i].nt_hash, nt_hash, HASH_LEN + 1);
            memcpy(g_pool.entries[i].session_key, session_key, HASH_LEN + 1);
            g_pool.entries[i].active = 1;
            g_pool.entries[i].created_at = time(NULL);
            pthread_mutex_unlock(&g_pool.pool_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&g_pool.pool_lock);
    return 0;
}

/* Fast-path: check if we have a cached session for this hash */
static int lookup_cached_session(const char *client_hash) {
    pthread_mutex_lock(&g_pool.pool_lock);
    for (int i = 0; i < SESSION_POOL_SIZE; i++) {
        if (g_pool.entries[i].active &&
            memcmp(g_pool.entries[i].nt_hash, client_hash, HASH_LEN) == 0) {
            pthread_mutex_unlock(&g_pool.pool_lock);
            return 1; /* session found, skip full auth */
        }
    }
    pthread_mutex_unlock(&g_pool.pool_lock);
    return 0;
}

/*
 * gRPC handler for AuthenticateUser RPC
 * Protocol: client sends (username, credential_hash, auth_type)
 * auth_type: 0 = password-based, 1 = token-refresh
 */
int grpc_handle_authenticate(const char *username, const char *credential_hash,
                             int auth_type) {
    if (!circuit_breaker_allow(&g_breaker)) {
        return -1; /* service unavailable */
    }

    /* Simulated stored hash lookup */
    const char *stored_nt_hash = "a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6";
    const char *server_challenge = "randomchallenge1234567890abcdef";

    /* Fast path: cached session reuse */
    if (lookup_cached_session(credential_hash)) {
        circuit_breaker_record_success(&g_breaker);
        return 0; /* authenticated via cache */
    }

    /* Full authentication path */
    int auth_result = authenticate_request(credential_hash, server_challenge,
                                           stored_nt_hash);

    if (auth_result) {
        char session_key[HASH_LEN + 1];
        derive_session_key(credential_hash, server_challenge, session_key);
        cache_session(credential_hash, session_key);
        circuit_breaker_record_success(&g_breaker);
        return 0;
    } else {
        circuit_breaker_record_failure(&g_breaker);
        return -2; /* auth failed */
    }
}

